/* gemm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations applied:
 *  - 3D blocking (tiling) in i, j, k to improve cache reuse.
 *  - j kept as innermost loop for unit-stride SIMD-friendly access.
 *  - Hoisting of alpha*A[i][k] out of the innermost j loop.
 *  - Use of restrict-qualified local pointers to help the compiler
 *    with alias analysis and vectorization.
 *  - Optional OpenMP parallelization over outer i/j tiles (ignored
 *    by compilers that do not enable OpenMP).
 *
 * The computation performed is still:
 *   for all (i,j):
 *     C[i,j] = beta * C[i,j] + alpha * sum_k A[i,k] * B[k,j]
 *
 * The order of operations for each individual C[i,j] is preserved:
 *   1) scale by beta, then
 *   2) add contributions for k = 0..NK-1 in increasing k.
 */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  /* Local copies of sizes (for use in VLAs / pointer types). */
  const int ni_ = ni;
  const int nj_ = nj;
  const int nk_ = nk;

  /* Restrict-qualified views of the matrices.
   * POLYBENCH_2D expands to a VLA type like DATA_TYPE C[ni][nj];
   * we create explicit pointer aliases so the compiler understands
   * there is no aliasing between A, B, and C, which helps
   * vectorization and other optimizations.
   */
  DATA_TYPE (*restrict C_)[nj_] = C;
  DATA_TYPE (*restrict A_)[nk_] = A;
  DATA_TYPE (*restrict B_)[nj_] = B;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  /* Tile sizes: chosen conservatively to work well across a range
   * of cache sizes. They can be tuned further for a specific target.
   *
   * With TI=TJ=32:
   *   - A tile of size TI x TK and B tile TK x TJ (with TK=32)
   *     are small enough to comfortably fit in L1/L2.
   */
  const int TI = 32;
  const int TJ = 32;
  const int TK = 32;

  int ii, jj, kk;

  //BLAS PARAMS
  //TRANSA = 'N'
  //TRANSB = 'N'
  // => Form C := alpha*A*B + beta*C,
  //A is NIxNK
  //B is NKxNJ
  //C is NIxNJ
#pragma scop
  /* 3D blocked version of:
   *
   * for (i = 0; i < _PB_NI; i++) {
   *   for (j = 0; j < _PB_NJ; j++)
   *     C[i][j] *= beta;
   *   for (k = 0; k < _PB_NK; k++) {
   *     for (j = 0; j < _PB_NJ; j++)
   *       C[i][j] += alpha * A[i][k] * B[k][j];
   *   }
   * }
   *
   * We preserve the per-element operation order but process
   * C in tiles for better cache and TLB locality.
   */

  /* Parallelize over tiles of rows and columns of C.
   * Each (ii, jj) tile works on a disjoint submatrix of C, so
   * there are no write conflicts. If OpenMP is not enabled,
   * this pragma is ignored and execution remains sequential.
   */
#pragma omp parallel for collapse(2) schedule(static) default(shared) private(ii, jj, kk)
  for (ii = 0; ii < _PB_NI; ii += TI) {
    for (jj = 0; jj < _PB_NJ; jj += TJ) {

      /* Actual bounds of this tile (handle edge tiles). */
      int i_max = ii + TI;
      if (i_max > _PB_NI)
        i_max = _PB_NI;

      int j_max = jj + TJ;
      if (j_max > _PB_NJ)
        j_max = _PB_NJ;

      const int tile_j = j_max - jj;

      /* 1) Scale the current TI x TJ tile of C by beta.
       *    For each (i,j) in this tile, this is exactly the same
       *    operation as in the original first loop.
       */
      for (int i = ii; i < i_max; ++i) {
        /* Pointer to the first element of row i in this tile.
         * Accesses Ci[0..tile_j-1] correspond to C_[i][jj..j_max-1]
         * and are contiguous in memory, aiding SIMD.
         */
        DATA_TYPE *restrict Ci = &C_[i][jj];

        for (int j = 0; j < tile_j; ++j) {
          Ci[j] *= beta_local;
        }
      }

      /* 2) GEMM update for this tile:
       *    for each (i,j) in the tile:
       *      C[i,j] += alpha * sum_{k=0..NK-1} A[i,k] * B[k,j];
       *
       *    We iterate k in blocks of size TK to improve locality
       *    for both A and B. For each (i,k) pair, the product
       *    alpha * A[i,k] is hoisted out of the inner j-loop.
       */
      for (kk = 0; kk < _PB_NK; kk += TK) {
        int k_max = kk + TK;
        if (k_max > _PB_NK)
          k_max = _PB_NK;

        for (int i = ii; i < i_max; ++i) {
          DATA_TYPE *restrict Ci = &C_[i][jj];

          for (int k = kk; k < k_max; ++k) {
            /* Hoist multiplication by alpha out of the j-loop:
             *   a_ik = alpha * A[i,k];
             *   for j: C[i,j] += a_ik * B[k,j];
             */
            const DATA_TYPE a_ik = alpha_local * A_[i][k];
            const DATA_TYPE *restrict Bk = &B_[k][jj];

            /* Innermost loop over j: unit-stride accesses for
             * both C and B, which is ideal for auto-vectorization.
             */
            for (int j = 0; j < tile_j; ++j) {
              Ci[j] += a_ik * Bk[j];
            }
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
