/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"

/* ---------------------------------------------------------------------
 * Tunable blocking (tiling) parameters for GEMM.
 *
 * These tile sizes are chosen to give good cache behavior on a modern
 * x64 CPU. They can be adjusted at compile time by defining the macros
 * before including/compiling this file, without changing the code.
 * -------------------------------------------------------------------*/
#ifndef GEMM_TILE_I
# define GEMM_TILE_I 32  /* rows of C / A per tile */
#endif

#ifndef GEMM_TILE_J
# define GEMM_TILE_J 32  /* columns of C / B per tile */
#endif

#ifndef GEMM_TILE_K
# define GEMM_TILE_K 32  /* inner dimension (k) per tile */
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
