  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimized version:
 *   - 3D cache blocking (tiling) over i, j, k.
 *   - Each C tile is loaded once, scaled by beta, accumulated over all k,
 *     and then written back once (improved locality and fewer C loads/stores).
 *   - Accesses to C[i][*] and B[k][*] are contiguous in memory in the
 *     innermost loop to help auto-vectorization.
 *   - The product alpha*A[i][k] is hoisted out of the innermost j-loop.
 *
 * Semantics are identical to the original:
 *   C = beta * C + alpha * A * B
 */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  /* Use the PolyBench loop bounds, which may differ from ni/nj/nk in
     some configurations (e.g., for validation). */
  const int ni_eff = _PB_NI;
  const int nj_eff = _PB_NJ;
  const int nk_eff = _PB_NK;

  /* Create local restrict-qualified views of the matrices.
   *
   * This tells the compiler that A, B, and C do not alias, which greatly
   * helps auto-vectorization and other optimizations. The underlying
   * storage is still exactly the same as in the original program.
   */
  DATA_TYPE (*restrict C_)[nj_eff] = C;
  DATA_TYPE (*restrict A_)[nk_eff] = A;
  DATA_TYPE (*restrict B_)[nj_eff] = B;

  /* Small tile of C kept in L1 cache / registers while sweeping k.
   *
   * Size is GEMM_TILE_I x GEMM_TILE_J, independent of problem size.
   * Each C element is:
   *   - loaded from memory once,
   *   - scaled by beta,
   *   - updated by all A*B contributions,
   *   - and finally written back once.
   *
   * The alignment hint can help SIMD loads/stores when the compiler
   * decides to vectorize the innermost loops.
   */
  DATA_TYPE C_tile[GEMM_TILE_I][GEMM_TILE_J]
    __attribute__ ((aligned (64)));

  int I, J, K;

  /* Original reference for comparison:
   *
   * for (i = 0; i < _PB_NI; i++) {
   *   for (j = 0; j < _PB_NJ; j++)
   *     C[i][j] *= beta;
   *   for (k = 0; k < _PB_NK; k++) {
   *     for (j = 0; j < _PB_NJ; j++)
   *       C[i][j] += alpha * A[i][k] * B[k][j];
   *   }
   * }
   */

#pragma scop
  /* 3D blocking:
   *   - I: tiles of rows (i) of size GEMM_TILE_I
   *   - J: tiles of cols (j) of size GEMM_TILE_J
   *   - K: tiles of k-dimension of size GEMM_TILE_K
   */
  for (I = 0; I < ni_eff; I += GEMM_TILE_I) {
    const int i_max = (I + GEMM_TILE_I < ni_eff) ? (I + GEMM_TILE_I) : ni_eff;
    const int tile_i = i_max - I;

    for (J = 0; J < nj_eff; J += GEMM_TILE_J) {
      const int j_max = (J + GEMM_TILE_J < nj_eff) ? (J + GEMM_TILE_J) : nj_eff;
      const int tile_j = j_max - J;

      int ii, jj, kk;

      /* ----------------------------------------------------------------
       * 1. Load a tile of C and scale it by beta.
       *    This fuses the original "C[i][j] *= beta" with tiling:
       *       C_tile[ii][jj] = beta * C[I+ii][J+jj].
       * ---------------------------------------------------------------- */
      for (ii = 0; ii < tile_i; ++ii) {
        DATA_TYPE *restrict c_global_row = &C_[I + ii][J];
        DATA_TYPE *restrict c_tile_row   = &C_tile[ii][0];

        /* j-loop is unit-stride over both c_global_row and c_tile_row */
        #pragma GCC ivdep
        for (jj = 0; jj < tile_j; ++jj) {
          c_tile_row[jj] = beta * c_global_row[jj];
        }
      }

      /* ----------------------------------------------------------------
       * 2. Accumulate A*B contributions into the C tile over all k-blocks.
       *
       *    For each K-tile:
       *      for ii in rows of tile I:
       *        for kk in [K, k_max):
       *          a_ik = alpha * A[I+ii][kk];      (hoisted out of j-loop)
       *          for jj in cols of tile J:
       *            C_tile[ii][jj] += a_ik * B[kk][J+jj];
       *
       *    Over all K-tiles this computes
       *      C_tile[ii][jj] = beta * C_orig[I+ii][J+jj]
       *                       + alpha * sum_k A[I+ii][k] * B[k][J+jj]
       * ---------------------------------------------------------------- */
      for (K = 0; K < nk_eff; K += GEMM_TILE_K) {
        const int k_max = (K + GEMM_TILE_K < nk_eff) ? (K + GEMM_TILE_K) : nk_eff;

        for (ii = 0; ii < tile_i; ++ii) {
          const int i_idx = I + ii;

          for (kk = K; kk < k_max; ++kk) {
            const DATA_TYPE a_ik = alpha * A_[i_idx][kk];
            const DATA_TYPE *restrict b_row = &B_[kk][J];
            DATA_TYPE *restrict c_tile_row  = &C_tile[ii][0];

            /* Innermost loop over j:
             *   - C_tile[ii][*] and B[kk][*] are both contiguous in memory.
             *   - This pattern is ideal for SIMD vectorization.
             */
            #pragma GCC ivdep
            for (jj = 0; jj < tile_j; ++jj) {
              c_tile_row[jj] += a_ik * b_row[jj];
            }
          }
        }
      }

      /* ----------------------------------------------------------------
       * 3. Store the completed C tile back to global memory.
       *    Each element is written exactly once.
       * ---------------------------------------------------------------- */
      for (ii = 0; ii < tile_i; ++ii) {
        DATA_TYPE *restrict c_global_row = &C_[I + ii][J];
        DATA_TYPE *restrict c_tile_row   = &C_tile[ii][0];

        #pragma GCC ivdep
        for (jj = 0; jj < tile_j; ++jj) {
          c_global_row[jj] = c_tile_row[jj];
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
