  DATA_TYPE C_tile[GEMM_BLOCK_I][GEMM_BLOCK_J]
    __attribute__((aligned(64)));

  /* Cached block sizes (allow the compiler to treat them as locals). */
  const int T_I = GEMM_BLOCK_I;
  const int T_J = GEMM_BLOCK_J;
  const int T_K = GEMM_BLOCK_K;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop
  /* Outer blocking over i and j: operate on a tile of C at a time. */
  for (int ii = 0; ii < _PB_NI; ii += T_I)
  {
    const int i_max = (ii + T_I < _PB_NI) ? (ii + T_I) : _PB_NI;
    const int tile_i = i_max - ii;

    for (int jj = 0; jj < _PB_NJ; jj += T_J)
    {
      const int j_max = (jj + T_J < _PB_NJ) ? (jj + T_J) : _PB_NJ;
      const int tile_j = j_max - jj;

      /* 1. Load the current C tile and apply the beta scaling.
       *
       *    After this loop:
       *      C_tile[ti][tj] = beta * C[ii + ti][jj + tj]
       *
       *    We do this once per tile, then accumulate alpha*A*B into
       *    C_tile in the next phase.
       */
      for (int ti = 0; ti < tile_i; ++ti)
      {
        const int i = ii + ti;
        DATA_TYPE *restrict C_row       = &C[i][jj];
        DATA_TYPE *restrict C_tile_row  = &C_tile[ti][0];

        for (int tj = 0; tj < tile_j; ++tj)
        {
          C_tile_row[tj] = C_row[tj] * beta;
        }
      }

      /* 2. Accumulate alpha * A * B into the local C_tile.
       *
       *    Loop order inside tiles: i -> k -> j
       *    - A[i,k] is accessed with unit stride along k.
       *    - B[k,j] and C_tile[ti][tj] are accessed with unit stride
       *      along j, which is favorable for SIMD.
       */
      for (int kk = 0; kk < _PB_NK; kk += T_K)
      {
        const int k_max = (kk + T_K < _PB_NK) ? (kk + T_K) : _PB_NK;

        for (int ti = 0; ti < tile_i; ++ti)
        {
          const int i = ii + ti;
          const DATA_TYPE *restrict A_row = &A[i][0];
          DATA_TYPE *restrict C_tile_row  = &C_tile[ti][0];

          /* Iterate over the current k-block. */
          for (int k = kk; k < k_max; ++k)
          {
            const DATA_TYPE a_ik_alpha = alpha * A_row[k];
            const DATA_TYPE *restrict B_row = &B[k][jj];

            /* Innermost loop over j: contiguous in memory for B and C,
             * enabling efficient vectorization by the compiler.
             */
            for (int tj = 0; tj < tile_j; ++tj)
            {
              C_tile_row[tj] += a_ik_alpha * B_row[tj];
            }
          }
        }
      }

      /* 3. Write the updated tile back to C.
       *
       *    Each element C[i][j] is written exactly once after all
       *    contributions from the k-dimension have been accumulated.
       */
      for (int ti = 0; ti < tile_i; ++ti)
      {
        const int i = ii + ti;
        DATA_TYPE *restrict C_row              = &C[i][jj];
        const DATA_TYPE *restrict C_tile_row   = &C_tile[ti][0];

        for (int tj = 0; tj < tile_j; ++tj)
        {
          C_row[tj] = C_tile_row[tj];
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
